CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE warehouse(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,address text NOT NULL,capacity numeric(14,3) NOT NULL CHECK(capacity>0),temperature numeric(6,2) NOT NULL,active boolean NOT NULL DEFAULT true,location geometry(Point,4326) NOT NULL);
CREATE TABLE app_user(id bigserial PRIMARY KEY,email text UNIQUE NOT NULL,password text NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('ADMIN','WAREHOUSE','DISPATCH')),warehouse_id bigint REFERENCES warehouse,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACTIVE','LOCKED')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(role<>'WAREHOUSE' OR status<>'ACTIVE' OR warehouse_id IS NOT NULL));
CREATE TABLE sku(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,name_en text NOT NULL DEFAULT '',category text NOT NULL,pack_kg numeric(10,3) NOT NULL CHECK(pack_kg>0),weight_tolerance numeric(5,2) NOT NULL DEFAULT 15 CHECK(weight_tolerance BETWEEN 0 AND 100),temp_min numeric(6,2) NOT NULL,temp_max numeric(6,2) NOT NULL,min_days int NOT NULL DEFAULT 7 CHECK(min_days>=0),warning_days int NOT NULL DEFAULT 30 CHECK(warning_days>=0),min_stock numeric(14,3) NOT NULL DEFAULT 500 CHECK(min_stock>=0),active boolean NOT NULL DEFAULT true,CHECK(temp_min<=temp_max));
CREATE TABLE partner(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('SUPPLIER','CUSTOMER','CARRIER')),country text NOT NULL,address text NOT NULL,email text,phone text,active boolean NOT NULL DEFAULT true);
CREATE TABLE lot(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,sku_id bigint NOT NULL REFERENCES sku,supplier_id bigint NOT NULL REFERENCES partner,origin text NOT NULL,manufactured date NOT NULL,expires date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(expires>manufactured));
CREATE TABLE demand(id bigserial PRIMARY KEY,warehouse_id bigint NOT NULL REFERENCES warehouse,sku_id bigint NOT NULL REFERENCES sku,kind text NOT NULL CHECK(kind IN ('SHORTAGE','SURPLUS')),kg numeric(14,3) NOT NULL CHECK(kg>0),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','FULFILLED')),created_by bigint NOT NULL REFERENCES app_user,approved_by bigint REFERENCES app_user,decision text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(created_by IS DISTINCT FROM approved_by));
CREATE TABLE operation(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,kind text NOT NULL CHECK(kind IN ('IMPORT','EXPORT','DOMESTIC','TRANSFER')),source_id bigint REFERENCES warehouse,destination_id bigint REFERENCES warehouse,partner_id bigint REFERENCES partner,demand_id bigint REFERENCES demand,origin_place text NOT NULL,destination_place text NOT NULL,planned_date date NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PENDING','APPROVED','IN_PROGRESS','COMPLETED','REJECTED','CANCELLED')),created_by bigint NOT NULL REFERENCES app_user,approved_by bigint REFERENCES app_user,decision text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(created_by IS DISTINCT FROM approved_by),CHECK((kind='IMPORT' AND source_id IS NULL AND destination_id IS NOT NULL AND partner_id IS NOT NULL) OR (kind IN ('EXPORT','DOMESTIC') AND source_id IS NOT NULL AND destination_id IS NULL AND partner_id IS NOT NULL) OR (kind='TRANSFER' AND source_id IS NOT NULL AND destination_id IS NOT NULL AND source_id<>destination_id)));
CREATE TABLE operation_line(id bigserial PRIMARY KEY,operation_id bigint NOT NULL REFERENCES operation,sku_id bigint NOT NULL REFERENCES sku,lot_id bigint REFERENCES lot,kg numeric(14,3) NOT NULL CHECK(kg>0),boxes int NOT NULL CHECK(boxes>0),price numeric(16,2) NOT NULL DEFAULT 0 CHECK(price>=0));
CREATE TABLE stock(id bigserial PRIMARY KEY,warehouse_id bigint NOT NULL REFERENCES warehouse,lot_id bigint NOT NULL REFERENCES lot,kg numeric(14,3) NOT NULL DEFAULT 0,boxes int NOT NULL DEFAULT 0,blocked numeric(14,3) NOT NULL DEFAULT 0,blocked_boxes int NOT NULL DEFAULT 0,reserved numeric(14,3) NOT NULL DEFAULT 0,reserved_boxes int NOT NULL DEFAULT 0,version int NOT NULL DEFAULT 0,UNIQUE(warehouse_id,lot_id),CHECK(kg>=0 AND boxes>=0 AND blocked>=0 AND reserved>=0 AND blocked_boxes>=0 AND reserved_boxes>=0 AND blocked+reserved<=kg AND blocked_boxes+reserved_boxes<=boxes));
CREATE TABLE allocation(id bigserial PRIMARY KEY,line_id bigint NOT NULL REFERENCES operation_line,stock_id bigint REFERENCES stock,lot_id bigint NOT NULL REFERENCES lot,kg numeric(14,3) NOT NULL CHECK(kg>0),boxes int NOT NULL CHECK(boxes>0),shipped numeric(14,3) NOT NULL DEFAULT 0,shipped_boxes int NOT NULL DEFAULT 0,CHECK(shipped BETWEEN 0 AND kg AND shipped_boxes BETWEEN 0 AND boxes));
CREATE TABLE batch(id bigserial PRIMARY KEY,operation_id bigint NOT NULL REFERENCES operation,code text UNIQUE NOT NULL,planned_date date NOT NULL,customs text NOT NULL DEFAULT 'PENDING' CHECK(customs IN ('PENDING','PROCESSING','PASSED','REJECTED')),quality text NOT NULL DEFAULT 'PENDING' CHECK(quality IN ('PENDING','PASSED','FAILED','QUARANTINE')),reason text,disposition text,created_by bigint NOT NULL REFERENCES app_user);
CREATE TABLE resource(id bigserial PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('CONTAINER','TRACTOR','TRAILER','DRIVER')),code text UNIQUE NOT NULL,name text NOT NULL,owned boolean NOT NULL DEFAULT true,partner_id bigint REFERENCES partner,payload numeric(14,3) NOT NULL DEFAULT 25000 CHECK(payload>0),type_code text NOT NULL DEFAULT '45R1',temp_min numeric(6,2) NOT NULL DEFAULT -30,temp_max numeric(6,2) NOT NULL DEFAULT 10,place text NOT NULL,status text NOT NULL DEFAULT 'READY' CHECK(status IN ('READY','BUSY','MAINTENANCE','RETURNED')),license_expiry date,phone text,CHECK(temp_min<=temp_max),CHECK(owned OR partner_id IS NOT NULL));
CREATE TABLE trip(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,batch_id bigint REFERENCES batch,kind text NOT NULL DEFAULT 'CARGO' CHECK(kind IN ('CARGO','REPOSITION')),container_id bigint NOT NULL REFERENCES resource,tractor_id bigint NOT NULL REFERENCES resource,trailer_id bigint NOT NULL REFERENCES resource,driver_id bigint NOT NULL REFERENCES resource,origin_place text NOT NULL,destination_place text NOT NULL,departure_at timestamptz NOT NULL,temperature numeric(6,2) NOT NULL DEFAULT -20,status text NOT NULL DEFAULT 'ASSIGNED' CHECK(status IN ('ASSIGNED','MOVING','ARRIVED','RECEIVING','UNLOADED','WAIT_RETURN','CLOSED','CANCELLED')),return_result text,created_by bigint NOT NULL REFERENCES app_user,CHECK((kind='CARGO' AND batch_id IS NOT NULL) OR (kind='REPOSITION' AND batch_id IS NULL)));
CREATE UNIQUE INDEX busy_container ON trip(container_id) WHERE status NOT IN ('CLOSED','CANCELLED');
CREATE UNIQUE INDEX busy_tractor ON trip(tractor_id) WHERE status NOT IN ('CLOSED','CANCELLED');
CREATE UNIQUE INDEX busy_trailer ON trip(trailer_id) WHERE status NOT IN ('CLOSED','CANCELLED');
CREATE UNIQUE INDEX busy_driver ON trip(driver_id) WHERE status NOT IN ('CLOSED','CANCELLED');
CREATE TABLE trip_line(id bigserial PRIMARY KEY,trip_id bigint NOT NULL REFERENCES trip,allocation_id bigint NOT NULL REFERENCES allocation,kg numeric(14,3) NOT NULL CHECK(kg>0),boxes int NOT NULL CHECK(boxes>0),UNIQUE(trip_id,allocation_id));
CREATE TABLE receipt(id bigserial PRIMARY KEY,trip_id bigint UNIQUE NOT NULL REFERENCES trip,warehouse_id bigint REFERENCES warehouse,created_by bigint NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now(),note text NOT NULL,temperature numeric(6,2) NOT NULL);
CREATE TABLE receipt_line(id bigserial PRIMARY KEY,receipt_id bigint NOT NULL REFERENCES receipt,trip_line_id bigint UNIQUE NOT NULL REFERENCES trip_line,actual numeric(14,3) NOT NULL CHECK(actual>=0),boxes int NOT NULL CHECK(boxes>=0),blocked numeric(14,3) NOT NULL DEFAULT 0 CHECK(blocked>=0 AND blocked<=actual),blocked_boxes int NOT NULL DEFAULT 0 CHECK(blocked_boxes>=0 AND blocked_boxes<=boxes));
CREATE TABLE discrepancy(id bigserial PRIMARY KEY,receipt_line_id bigint UNIQUE NOT NULL REFERENCES receipt_line,reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RESOLVED')),resolution text,decision text,created_by bigint NOT NULL REFERENCES app_user,approved_by bigint REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now(),CHECK(created_by IS DISTINCT FROM approved_by));
CREATE TABLE movement(id bigserial PRIMARY KEY,warehouse_id bigint NOT NULL REFERENCES warehouse,lot_id bigint NOT NULL REFERENCES lot,operation_id bigint REFERENCES operation,trip_id bigint REFERENCES trip,kind text NOT NULL,delta numeric(14,3) NOT NULL,delta_boxes int NOT NULL,before_kg numeric(14,3) NOT NULL,after_kg numeric(14,3) NOT NULL,actor_id bigint NOT NULL REFERENCES app_user,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_count(id bigserial PRIMARY KEY,stock_id bigint NOT NULL REFERENCES stock,expected numeric(14,3) NOT NULL,expected_boxes int NOT NULL,stock_version int NOT NULL,actual numeric(14,3) NOT NULL CHECK(actual>=0),actual_boxes int NOT NULL CHECK(actual_boxes>=0),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')),created_by bigint NOT NULL REFERENCES app_user,approved_by bigint REFERENCES app_user,decision text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(created_by IS DISTINCT FROM approved_by));
CREATE TABLE goods_return(id bigserial PRIMARY KEY,receipt_line_id bigint NOT NULL REFERENCES receipt_line,warehouse_id bigint NOT NULL REFERENCES warehouse,kg numeric(14,3) NOT NULL CHECK(kg>0),boxes int NOT NULL CHECK(boxes>0),reason text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','RECEIVED','RESOLVED','REJECTED')),resolution text,created_by bigint NOT NULL REFERENCES app_user,approved_by bigint REFERENCES app_user,CHECK(created_by IS DISTINCT FROM approved_by));
CREATE TABLE document(id bigserial PRIMARY KEY,operation_id bigint NOT NULL REFERENCES operation,batch_id bigint REFERENCES batch,trip_id bigint REFERENCES trip,kind text NOT NULL,number text UNIQUE NOT NULL,language text NOT NULL CHECK(language IN ('VI','EN')),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED')),fields jsonb NOT NULL DEFAULT '{}',snapshot jsonb,created_by bigint NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachment(id bigserial PRIMARY KEY,document_id bigint NOT NULL REFERENCES document,name text NOT NULL,mime text NOT NULL,bytes bytea NOT NULL,sha256 text NOT NULL,created_by bigint NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE position(id bigserial PRIMARY KEY,trip_id bigint NOT NULL REFERENCES trip,location geometry(Point,4326) NOT NULL,recorded_at timestamptz NOT NULL,source text NOT NULL DEFAULT 'MANUAL',note text NOT NULL,actor_id bigint NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX position_geo ON position USING gist(location);
CREATE INDEX position_trip ON position(trip_id,recorded_at);
CREATE TABLE audit(id bigserial PRIMARY KEY,actor_id bigint REFERENCES app_user,action text NOT NULL,entity text NOT NULL,entity_id bigint,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE setting(key text PRIMARY KEY,value text NOT NULL);
INSERT INTO setting VALUES ('company_name','Công ty Hải sản Đại Dương (mô phỏng)'),('company_name_en','Ocean Seafood Company (Demo)'),('company_address','TP. Hồ Chí Minh, Việt Nam'),('company_address_en','Ho Chi Minh City, Vietnam');
CREATE VIEW stock_view AS SELECT s.*,w.name warehouse,l.code lot,k.code sku,k.name,k.category,l.expires,k.warning_days,k.min_days,k.min_stock,k.active,CASE WHEN k.active AND l.expires>=current_date+k.min_days THEN s.kg-s.blocked-s.reserved ELSE 0 END available,CASE WHEN k.active AND l.expires>=current_date+k.min_days THEN s.boxes-s.blocked_boxes-s.reserved_boxes ELSE 0 END available_boxes,l.sku_id FROM stock s JOIN warehouse w ON w.id=s.warehouse_id JOIN lot l ON l.id=s.lot_id JOIN sku k ON k.id=l.sku_id;
CREATE VIEW capacity_view AS SELECT w.id,w.code,w.name,w.capacity,w.temperature,coalesce((SELECT sum(s.kg) FROM stock s WHERE s.warehouse_id=w.id),0) used,coalesce((SELECT sum(l.kg-coalesce((SELECT sum(tl.kg) FROM trip_line tl JOIN trip t ON t.id=tl.trip_id JOIN receipt r ON r.trip_id=t.id JOIN allocation a ON a.id=tl.allocation_id WHERE a.line_id=l.id),0)) FROM operation_line l JOIN operation o ON o.id=l.operation_id WHERE o.destination_id=w.id AND o.status IN ('APPROVED','IN_PROGRESS')),0)+coalesce((SELECT sum(g.kg) FROM goods_return g WHERE g.warehouse_id=w.id AND g.status='APPROVED'),0) promised FROM warehouse w;
CREATE OR REPLACE FUNCTION deny_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only history'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION deny_history_change();
CREATE TRIGGER position_immutable BEFORE UPDATE OR DELETE ON position FOR EACH ROW EXECUTE FUNCTION deny_history_change();
CREATE TRIGGER movement_immutable BEFORE UPDATE OR DELETE ON movement FOR EACH ROW EXECUTE FUNCTION deny_history_change();

CREATE OR REPLACE FUNCTION freeze_confirmed_document() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='CONFIRMED' THEN RAISE EXCEPTION 'Confirmed document is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER document_immutable BEFORE UPDATE OR DELETE ON document FOR EACH ROW EXECUTE FUNCTION freeze_confirmed_document();
CREATE TRIGGER attachment_immutable BEFORE UPDATE OR DELETE ON attachment FOR EACH ROW EXECUTE FUNCTION deny_history_change();
